import React, { useState, useEffect } from 'react';
import { getContract, getAddress } from './contract';
import UploadForm from './components/UploadForm';
import AccessControl from './components/AccessControl';
import ViewRecords from './components/ViewRecords';
import './App.css';

function App() {
  const [account, setAccount] = useState('');
  const [contract, setContract] = useState(null);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('upload');

  useEffect(() => {
    const init = async () => {
      try {
        const contractData = await getContract();
        if (contractData) {
          setContract(contractData.contract);
          const addr = await getAddress();
          setAccount(addr);
        }
      } catch (error) {
        console.error("Error initializing app:", error);
      } finally {
        setLoading(false);
      }
    };

    init();

    // Listen for account changes
    if (window.ethereum) {
      window.ethereum.on('accountsChanged', (accounts) => {
        setAccount(accounts[0]);
      });
    }
  }, []);

  const connectWallet = async () => {
    try {
      const addr = await getAddress();
      setAccount(addr);
      const contractData = await getContract();
      setContract(contractData.contract);
    } catch (error) {
      console.error("Error connecting wallet:", error);
    }
  };

  if (loading) {
    return <div className="container">Loading...</div>;
  }

  return (
    <div className="container">
      <h1>HealthChain</h1>
      <h2>Secure Medical Records on Blockchain</h2>
      
      {!account ? (
        <div className="connect-wallet">
          <p>Please connect your wallet to continue</p>
          <button onClick={connectWallet}>Connect MetaMask</button>
        </div>
      ) : (
        <>
          <div className="account-info">
            <p>Connected Account: {account}</p>
          </div>
          
          <div className="tabs">
            <button 
              className={activeTab === 'upload' ? 'active' : ''} 
              onClick={() => setActiveTab('upload')}
            >
              Upload Record
            </button>
            <button 
              className={activeTab === 'access' ? 'active' : ''} 
              onClick={() => setActiveTab('access')}
            >
              Manage Access
            </button>
            <button 
              className={activeTab === 'view' ? 'active' : ''} 
              onClick={() => setActiveTab('view')}
            >
              View Records
            </button>
          </div>
          
          <div className="tab-content">
            {activeTab === 'upload' && <UploadForm contract={contract} account={account} />}
            {activeTab === 'access' && <AccessControl contract={contract} account={account} />}
            {activeTab === 'view' && <ViewRecords contract={contract} account={account} />}
          </div>
        </>
      )}
    </div>
  );
}

export default App;
